import {PRODUCTS,SIZES,FITS,EMPTY_ITEMS,measurements,orderStatus,isClosed,clone} from './domain.mjs';
import {DemoAPI,LiveAPI} from './api.mjs';
import {MannequinViewer} from './mannequin.mjs';
const cfg=window.THREADROOM_CONFIG||{};
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={shirt:'M16 3 21 6 18 10 16 9v12H8V9l-2 1-3-4 5-3c2 2 6 2 8 0Z',bag:'M6 7h12l2 14H4L6 7Zm3 0V5a3 3 0 0 1 6 0v2',history:'M3 11a9 9 0 1 1 3 7M3 4v7h7m2-5v6l4 2',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-2-5h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3 3-1Z',check:'m5 12 4 4L19 6',arrow:'M4 12h16m-6-6 6 6-6 6',rotate:'M20 8A8 8 0 1 0 20 16M20 3v5h-5',zoom:'M10 4a6 6 0 1 0 0 12 6 6 0 0 0 0-12Zm5 11 5 5M7 10h6m-3-3v6',mail:'M3 5h18v14H3V5Zm0 1 9 7 9-7',lock:'M5 10h14v11H5V10Zm3 0V6a4 4 0 0 1 8 0v4',info:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm0 9v6m0-11v1',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.shirt}"/></svg>`;
let api;
try{api=cfg.mode==='live'?new LiveAPI(cfg.apiUrl):new DemoAPI()}catch(e){$('#content').innerHTML=`<div class="empty-state"><h2>ยังตั้งค่าระบบไม่ครบ</h2><p>${esc(e.message)}</p></div>`;throw e}
const state={user:null,settings:{open:true,closeAt:'',revision:0},order:{items:clone(EMPTY_ITEMS),revision:0},logs:[],adminData:null,product:'polo',body:'female',angle:-.12,view:'front',auto:false,drafts:{polo:{size:'M',fit:'straight'},tee:{size:'M',fit:'straight'}},sampleSizes:true};
let viewer=null,toastTimer,busy=false,renderSequence=0;
const fmt=x=>x?new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(x)):'—';
const itemLabel=item=>item?`${FITS.find(f=>f.id===item.fit)?.name||''} · ${item.size}`:'ยังไม่ได้เลือก';
function notify(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').className=`toast show${error?' error':''}`;toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500)}
function route(){return location.hash.slice(1)||'fit'}
function closed(){return isClosed(state.settings)}
function disposeViewer(){if(viewer){state.angle=viewer.angle;viewer.destroy();viewer=null}}
function updateState(d){if(d.user)state.user=d.user;if(d.order){state.order=d.order;for(const p of PRODUCTS)if(d.order.items[p.id])state.drafts[p.id]=clone(d.order.items[p.id]);}if(d.logs)state.logs=d.logs;if(d.settings)state.settings=d.settings;if(d.sampleSizes!==undefined)state.sampleSizes=d.sampleSizes;chrome()}
function chrome(){
  const admin=state.user?.role==='admin',count=orderStatus(state.order.items).count;
  const navLink=(id,name,ic,extra='')=>`<a href="#${id}" class="${route()===id?'active':''}" ${route()===id?'aria-current="page"':''}>${icon(ic)}<span class="nav-label">${name}</span>${extra}</a>`;
  $('#nav').innerHTML=navLink('fit','ห้องลองเสื้อ','shirt')+navLink('orders','รายการของฉัน','bag',`<span class="nav-count">${count}/2</span>`)+navLink('history','ประวัติการแก้ไข','history')+(admin?'<div class="nav-divider"></div><div class="nav-section">ADMIN WORKSPACE</div>'+navLink('admin','จัดการผู้สั่งเสื้อ','grid')+navLink('settings','ตั้งค่าระบบ','settings'):'');
  $('#account-label').innerHTML=state.user?`${esc(state.user.name)}<span>${admin?'ผู้ดูแลระบบ':'ผู้สั่งเสื้อ'}${api.demo?' · ทดลอง':''}</span>`:'ทดลองใช้งาน<span>เลือกตัวตนเพื่อเริ่มต้น</span>';
  $('#avatar').textContent=state.user?.name?.slice(0,1)||'T';$('#login-top').textContent=state.user?'บัญชีของฉัน':'เข้าสู่ระบบ';
  $('#system-badge').className=`badge${closed()?' closed':''}`;$('#system-badge').innerHTML=`<i></i>${closed()?'ปิดรับการแก้ไขแล้ว':'เปิดรับการเลือกเสื้อ'}`;
  const mode=$('#mode-banner');mode.innerHTML=api.demo?`${icon('info')} โหมดทดลอง — ข้อมูลอยู่เฉพาะเบราว์เซอร์นี้ ยังไม่บันทึกลง Google Sheets และไม่ส่งอีเมล <span>DEMO VERSION</span>`:`${icon('info')} ${state.sampleSizes?'ตารางไซซ์และแบบเสื้อยังเป็นตัวอย่าง กรุณายืนยันข้อมูลจริงก่อนเปิดรับสั่ง':'บันทึกข้อมูลผ่านระบบสั่งเสื้อ'} <span>GOOGLE SHEETS</span>`;
  $('#footer-mode').textContent=api.demo?'DEMO / LOCAL DATA':'CONNECTED / GOOGLE SHEETS';
  const titles={fit:'ห้องลองเสื้อ',orders:'รายการของฉัน',history:'ประวัติการแก้ไข',admin:'จัดการผู้สั่งเสื้อ',settings:'ตั้งค่าระบบ'};$('#page-label').textContent=titles[route()]||titles.fit;
}
function intro(title,subtitle,eyebrow='MADE FOR OUR CLASS'){return `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="intro-text">${subtitle}</p></div><div class="edition">COLLECTION<strong>07.</strong></div></div>`}
function fitSvg(fit){return `<svg class="fit-outline" viewBox="0 0 28 32" aria-hidden="true"><path d="M9 2 2 7l4 6 3-2${fit==='shaped'?' 1 8-2 11h12l-2-11 1-8':'v19h12V11'}l3 2 4-6-7-5c-2 3-7 3-10 0Z"/></svg>`}
function renderFit(){
  const p=PRODUCTS.find(x=>x.id===state.product),draft=state.drafts[p.id],m=measurements(draft.size,draft.fit),count=orderStatus(state.order.items).count;
  const same=JSON.stringify(state.order.items[p.id])===JSON.stringify(draft),allSame=PRODUCTS.every(x=>JSON.stringify(state.order.items[x.id])===JSON.stringify(state.drafts[x.id]));
  $('#content').innerHTML=intro('เสื้อที่ใช่ ในสไตล์ของคุณ','ลองหมุนดู เลือกทรงที่ชอบ แล้วหาไซซ์ที่เป็นคุณ')+`
  <div class="fit-grid"><section class="fitting-column" aria-label="ภาพลองเสื้อ 360 องศา"><div class="viewer-card"><div class="viewer-header"><div class="viewer-tag">360° FITTING ROOM<strong>${p.label}</strong></div><div class="viewer-badge">3D PREVIEW</div></div><div class="viewer-area"><canvas id="mannequin" tabindex="0" role="img" aria-label="หุ่นจำลองใส่${p.name} ${itemLabel(draft)} ลากซ้ายขวาหรือใช้ปุ่มลูกศรเพื่อหมุนดู"></canvas><div class="dimension-chip">YOUR SELECTED SIZE<br><strong>${draft.size}</strong> <span>/ ${FITS.find(x=>x.id===draft.fit).name}</span></div><span class="angle-display" id="angle">000°</span></div><div class="viewer-controls"><button class="view-button ${state.view==='front'?'active':''}" data-action="view" data-view="front">ด้านหน้า</button><button class="view-button ${state.view==='back'?'active':''}" data-action="view" data-view="back">ด้านหลัง</button><button class="view-button ${state.auto?'active':''}" data-action="auto" aria-pressed="${state.auto}">${icon('rotate')} หมุนอัตโนมัติ</button><button class="view-button icon-only" data-action="zoom" aria-label="ซูมภาพหุ่น">${icon('zoom')}</button></div></div><p class="rotation-hint">${icon('rotate')} ลากซ้าย–ขวา เพื่อหมุนดูได้รอบตัว</p><div class="body-selector"><span class="field-title">เลือกหุ่นจำลอง <span>ไม่จำกัดเพศผู้สั่ง</span></span><div class="segmented" aria-label="หุ่นจำลอง"><button class="${state.body==='female'?'active':''}" data-action="body" data-value="female" aria-pressed="${state.body==='female'}">หุ่นผู้หญิง</button><button class="${state.body==='male'?'active':''}" data-action="body" data-value="male" aria-pressed="${state.body==='male'}">หุ่นผู้ชาย</button></div></div><p class="fitting-note">ภาพ 3 มิติแสดงสัดส่วนโดยประมาณตามไซซ์ ไม่ใช่การวัดตัวหรือการจำลองการทิ้งตัวของผ้าจริง ${state.sampleSizes?'ตารางไซซ์นี้เป็นข้อมูลตัวอย่าง รอตารางจากผู้ผลิต':''}</p></section>
  <section class="product-panel" aria-label="เลือกแบบและไซซ์เสื้อ"><div class="step-title"><strong>เริ่มจากเสื้อที่คุณชอบ</strong><span>01 — 02</span></div><div class="product-tabs">${PRODUCTS.map(x=>`<button class="product-tab ${x.id===p.id?'active':''}" data-action="product" data-value="${x.id}" aria-pressed="${x.id===p.id}"><i class="shirt-swatch" style="--shirt:${x.color}"></i><span class="product-tab-text">${x.name}<small>STYLE ${x.short}</small></span>${state.order.items[x.id]?'<span class="tiny-check">✓</span>':''}</button>`).join('')}</div><p class="product-label">${p.label}</p><h2 class="product-name">${p.name} ${p.id==='polo'?'สีกรมท่า':'สีครีม'}</h2><p class="product-subtitle">${p.subtitle}</p><div class="field-title">เลือกทรงเสื้อ<span>เลือกได้ทุกคน</span></div><div class="fit-options">${FITS.map(f=>`<button class="fit-option ${draft.fit===f.id?'active':''}" data-action="fit" data-value="${f.id}" aria-pressed="${draft.fit===f.id}">${fitSvg(f.id)}<span>${f.name}<small>${f.id==='straight'?'STRAIGHT FIT':'SHAPED FIT'}</small></span></button>`).join('')}</div><div class="field-title size-title">เลือกไซซ์<button class="size-guide" data-action="sizeguide">ดูตารางไซซ์ ↗</button></div><div class="sizes" aria-label="ไซซ์เสื้อ">${SIZES.map(s=>`<button class="size-button ${draft.size===s?'active':''}" data-action="size" data-value="${s}" aria-pressed="${draft.size===s}">${s}</button>`).join('')}</div><div class="size-measures"><div>รอบอก<strong>${m.chest}″</strong></div><div>รอบเอว<strong>${m.waist}″</strong></div><div>ความยาว<strong>${m.length}″</strong></div></div><p class="select-note">${state.sampleSizes?'ขนาดตัวอย่าง หน่วยนิ้ว · ยังไม่ใช่ขนาดจากผู้ผลิต':'ขนาดเสื้อ หน่วยนิ้ว'}<br>แต่ละแบบเลือกทรงและไซซ์ต่างกันได้</p><div class="action-stack"><button class="button wide" data-action="confirm-one" ${closed()||same?'disabled':''}>${icon(same?'check':'arrow')}${same?'ยืนยันแบบนี้แล้ว':'ยืนยันเสื้อตัวนี้'}</button><button class="button secondary wide" data-action="confirm-both" ${closed()||allSame?'disabled':''}>${icon('bag')} ยืนยันทั้ง 2 แบบ</button></div><p class="confirm-meta">${closed()?'ระบบปิดแล้ว เปิดดูรายการได้ตามปกติ':'เปลี่ยนใจได้ แก้ไขได้จนกว่าจะปิดระบบ'}</p></section></div>
  <div class="order-strip"><div class="strip-icon">${icon('bag')}</div><div><div class="strip-title">เสื้อรุ่น 1 เซ็ต ต้องมีครบ 2 แบบ</div><div class="strip-subtitle">${count===2?'คุณยืนยันครบแล้ว · ยังปรับเปลี่ยนได้ขณะเปิดระบบ':count===1?'ยืนยันแล้ว 1 แบบ · เลือกอีก 1 แบบให้ครบเซ็ต':'ยืนยันทีละตัว หรือพร้อมกันทั้งสองตัวได้เลย'}</div></div><div class="strip-progress"><i class="${count>=1?'done':''}"></i><i class="${count===2?'done':''}"></i></div><a class="strip-action" href="#orders">รายการของฉัน ↗</a></div>
  <div class="info-row"><div class="info-item"><span class="info-number">01 /</span><div><h3>ลองในแบบที่เป็นคุณ</h3><p>สลับหุ่น เลือกทรง หมุนดูได้ 360°</p></div></div><div class="info-item"><span class="info-number">02 /</span><div><h3>เลือกไว้ เปลี่ยนทีหลังได้</h3><p>ยืนยันแยกตัว พร้อมเก็บประวัติทุกครั้ง</p></div></div><div class="info-item"><span class="info-number">03 /</span><div><h3>แอดมินช่วยดูแล</h3><p>แจ้งอีเมลเมื่อแอดมินแก้ไขรายการ</p></div></div></div>`;
  viewer=new MannequinViewer($('#mannequin'),angle=>{if($('#angle'))$('#angle').textContent=String(angle).padStart(3,'0')+'°'},cfg.artwork||{});viewer.angle=state.angle;viewer.auto=state.auto;viewer.update({product:p.id,...draft,body:state.body});
}
function loginRequired(){return `<div class="empty-state"><div class="empty-symbol">↗</div><h2>เก็บตัวเลือกของคุณไว้ที่นี่</h2><p>เข้าสู่ระบบเพื่อยืนยันเสื้อทั้ง 2 แบบ<br>และกลับมาแก้ไขได้จนกว่าจะปิดระบบ</p><button class="button" data-action="login">${api.demo?'เริ่มทดลองใช้งาน':'เข้าสู่ระบบด้วยอีเมล'}</button></div>`}
function renderOrders(){const s=orderStatus(state.order.items);$('#content').innerHTML=intro('รายการของฉัน','เสื้อรุ่นของคุณทั้งสองแบบ อยู่ที่นี่','YOUR SELECTION')+(!state.user?loginRequired():`<div class="section-card"><div class="order-card-top"><div><h3>${esc(state.user.name)}</h3><p class="panel-note" style="margin-top:5px">${esc(state.user.email)} · ${s.label}</p></div><span class="status ${s.complete?'done':''}">${s.count} / 2 แบบ</span></div>${!s.complete?'<p class="warning-note">รายการยังไม่ครบเซ็ต กรุณายืนยันให้ครบทั้งสองแบบก่อนปิดระบบ</p>':''}</div><div class="order-cards">${PRODUCTS.map(p=>{const item=state.order.items[p.id];return `<section class="order-card"><div class="order-card-top"><div class="product-label">STYLE ${p.short}</div><span class="status ${item?'done':''}">${item?'ยืนยันแล้ว':'ยังไม่ได้เลือก'}</span></div><div class="order-card-visual"><i class="shirt-swatch" style="--shirt:${p.color}"></i></div><h3>${p.name}</h3><div class="order-details">${item?`<span>${FITS.find(f=>f.id===item.fit).name}</span><strong>SIZE ${item.size}</strong>`:'เลือกไซซ์และทรงที่คุณชอบ'}</div><div class="order-footer"><small>เลือกได้ทุกเพศ</small><button class="button small secondary" data-action="edit-own" data-value="${p.id}">${closed()?'ดูแบบเสื้อ':item?'แก้ไขตัวเลือก':'เลือกเสื้อตัวนี้'} ↗</button></div></section>`}).join('')}</div><p class="panel-note">บันทึกล่าสุด ${fmt(state.order.updatedAt)} · เวอร์ชัน ${state.order.revision} ${state.settings.closeAt?'· ปิดรับ '+fmt(state.settings.closeAt):''}</p><p class="fitting-note">ยืนยันหนึ่งแบบถือเป็นรายการที่ยังไม่ครบเซ็ต ระบบนับเป็นครบเมื่อยืนยันทั้งสองแบบเท่านั้น</p>`)}
function logEntry(log){const setting=log.action==='settings';return `<li><span class="timeline-dot"></span><div><time>${fmt(log.at)}</time><h3>${setting?'เปลี่ยนการตั้งค่าระบบ':log.action==='reset'?'ล้างรายการเพื่อเลือกใหม่':log.role==='admin'?'แอดมินแก้ไขรายการ':'ยืนยัน / เปลี่ยนตัวเลือกเสื้อ'}</h3><p>โดย ${esc(log.actor)}${log.reason?' · '+esc(log.reason):''}${log.email?' · '+esc(log.email):''}</p>${!setting?`<div class="change-chips">${PRODUCTS.filter(p=>JSON.stringify(log.before?.[p.id])!==JSON.stringify(log.after?.[p.id])).map(p=>`<span class="change-chip">${p.name}: ${esc(itemLabel(log.before?.[p.id]))} → ${esc(itemLabel(log.after?.[p.id]))}</span>`).join('')}</div>`:`<p>${log.after.open?'เปิดรับ':'ปิดรับ'} · กำหนดปิด ${fmt(log.after.closeAt)}</p>`}${log.role==='admin'&&log.email?`<span class="mail-tag">${api.demo?'ทดลองแจ้งเตือน · ไม่มีอีเมลส่งจริง':'อีเมลแจ้งเตือนอยู่ในคิวของระบบ'}</span>`:''}</div></li>`}
function renderHistory(){const logs=[...state.logs].reverse();$('#content').innerHTML=intro('ทุกการเปลี่ยนแปลง มีที่มา','ดูตัวเลือกเดิม ตัวเลือกใหม่ และผู้แก้ไขได้ทุกครั้ง','SELECTION HISTORY')+(!state.user?loginRequired():logs.length?`<div class="section-card"><ul class="timeline">${logs.map(logEntry).join('')}</ul></div>`:`<div class="empty-state"><div class="empty-symbol">↺</div><h2>ยังไม่มีประวัติการแก้ไข</h2><p>เมื่อคุณยืนยันหรือปรับเปลี่ยนเสื้อ<br>ระบบจะบันทึกประวัติไว้ที่นี่</p><a href="#fit" class="button secondary">ไปเลือกเสื้อ ↗</a></div>`)}
function adminRows(orders,search=''){const q=search.trim().toLowerCase();return orders.filter(o=>(o.name+' '+o.email).toLowerCase().includes(q)).map(o=>`<tr><td>${esc(o.name)}<small>${esc(o.email)}</small></td><td>${esc(itemLabel(o.items.polo))}</td><td>${esc(itemLabel(o.items.tee))}</td><td><span class="status ${orderStatus(o.items).complete?'done':''}">${orderStatus(o.items).label}</span></td><td><div class="table-actions"><button class="text-button" data-action="admin-edit" data-email="${esc(o.email)}" ${closed()?'disabled':''}>แก้ไข</button><button class="text-button red" data-action="admin-reset" data-email="${esc(o.email)}" ${closed()?'disabled':''}>ล้างรายการ</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="table-empty">ยังไม่มีรายการที่ตรงกับการค้นหา</td></tr>'}
async function renderAdmin(seq){if(state.user?.role!=='admin'){ $('#content').innerHTML=intro('พื้นที่สำหรับผู้ดูแล','เข้าสู่ระบบด้วยบัญชีแอดมินเพื่อจัดการผู้สั่ง','ADMIN WORKSPACE')+loginRequired();return}$('#content').innerHTML='<div class="loading"><span class="spinner"></span>กำลังโหลดรายการ</div>';const d=await api.admin();if(seq!==renderSequence)return;state.adminData=d;state.settings=d.settings;chrome();const complete=d.orders.filter(o=>orderStatus(o.items).complete).length,total=d.orders.reduce((n,o)=>n+orderStatus(o.items).count,0),pending=d.outbox.filter(x=>x.status==='pending').length;
  $('#content').innerHTML=intro('ดูแลทุกตัวเลือกของเพื่อน','แก้ไขให้เพื่อน ล้างรายการเพื่อเลือกใหม่ และตรวจสอบประวัติ','ADMIN WORKSPACE')+`<div class="stat-grid"><div class="stat-card"><span>ผู้สั่งทั้งหมด</span><strong>${d.orders.length}</strong><small>คนที่มีรายการในระบบ</small></div><div class="stat-card"><span>เลือกครบสองแบบ</span><strong>${complete}</strong><small>พร้อมสรุปยอด</small></div><div class="stat-card"><span>เสื้อที่ยืนยันแล้ว</span><strong>${total}</strong><small>ตัว จาก 2 แบบ</small></div><div class="stat-card"><span>${api.demo?'อีเมลจำลอง':'อีเมลรอส่ง / ส่งไม่สำเร็จ'}</span><strong>${api.demo?d.outbox.length:pending+d.outbox.filter(x=>x.status==='failed').length}</strong><small>${api.demo?'ไม่ส่งจริง':'ตรวจสอบที่แท็บ Outbox'}</small></div></div><div class="section-card"><div class="table-tools"><input id="admin-search" class="search" placeholder="ค้นหาชื่อ หรืออีเมล" aria-label="ค้นหาผู้สั่ง"><div>${api.demo?'<button class="button small secondary" data-action="seed">เพิ่มสมาชิกตัวอย่าง</button> ':''}<button class="button small secondary" data-action="refresh">โหลดข้อมูลล่าสุด ↻</button> <button class="button small secondary" data-action="export">${icon('download')} CSV</button></div></div><div class="table-wrap"><table><thead><tr><th>ผู้สั่ง</th><th>01 / เสื้อโปโล</th><th>02 / เสื้อยืด</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody id="admin-rows">${adminRows(d.orders)}</tbody></table></div><p class="panel-note">การล้างจะยกเลิกตัวเลือกปัจจุบัน เพื่อให้เจ้าของรายการเลือกใหม่ โดยเก็บข้อมูลเดิมในประวัติ และ${api.demo?'จำลองการแจ้งเตือน':'เข้าคิวส่งอีเมลแจ้งเจ้าของรายการ'}</p></div>${d.logs.length?`<div class="section-card"><h3 style="margin-bottom:22px">การเปลี่ยนแปลงล่าสุด</h3><ul class="timeline">${d.logs.slice(-8).reverse().map(logEntry).join('')}</ul></div>`:''}`;
}
async function renderSettings(seq){if(state.user?.role!=='admin'){renderOrders();return}const d=await api.admin();if(seq!==renderSequence)return;state.adminData=d;state.settings=d.settings;chrome();let localTime='';if(d.settings.closeAt){const date=new Date(d.settings.closeAt);localTime=new Date(date-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}$('#content').innerHTML=intro('ตั้งค่ารอบการสั่งเสื้อ','ควบคุมเวลาเปิดรับ และดูความพร้อมก่อนใช้งานจริง','SYSTEM SETTINGS')+`<div class="settings-grid"><section class="section-card"><h3>ช่วงเวลารับเลือกเสื้อ</h3><p class="panel-note">เมื่อปิดระบบ ผู้สั่งและแอดมินจะดูรายการได้ แต่แก้ไขไม่ได้จนกว่าจะเปิดใหม่</p><form id="settings-form"><label class="switch-line"><span>เปิดรับการเลือกและแก้ไข</span><input type="checkbox" name="open" ${d.settings.open?'checked':''} aria-label="เปิดรับการเลือกเสื้อ"></label><div class="form-row"><label for="closeAt">ปิดรับอัตโนมัติ</label><input id="closeAt" name="closeAt" type="datetime-local" value="${localTime}"><small>เวลาท้องถิ่นของอุปกรณ์นี้ · เว้นว่างเพื่อไม่ตั้งเวลา<br>เวลาปัจจุบันในประเทศไทย: ${fmt(new Date().toISOString())}</small></div><div class="form-row"><button class="button wide" type="submit">บันทึกการตั้งค่า</button></div></form></section><section class="section-card"><h3>สถานะระบบ</h3><div class="connection-status">${icon('info')} ${api.demo?'โหมดทดลองบนเบราว์เซอร์':'เชื่อมต่อ Google Apps Script'}</div><p class="panel-note">${api.demo?'ข้อมูลในหน้านี้เป็นการทดลองส่วนตัว ยังไม่เชื่อม Sheets และไม่ส่งอีเมลจริง':'บันทึกคำสั่งซื้อและประวัติลง Sheets · ใช้อีเมล OTP เพื่อยืนยันเจ้าของรายการ'}</p><p class="warning-note">แบบเสื้อและตารางไซซ์${state.sampleSizes?'ยังเป็นข้อมูลตัวอย่าง':'ตั้งค่าแล้ว'} ต้องตรวจเทียบกับผู้ผลิตก่อนเปิดใช้จริง หุ่น 3 มิติเป็นภาพประมาณการ</p><p class="panel-note">ไฟล์ตั้งค่า: <span class="code-inline">dist/config.js</span><br>คู่มือติดตั้งอยู่ในไฟล์ README ของชุดโค้ด</p>${api.demo?'<button class="button small secondary" style="margin-top:18px" data-action="clear-demo">ล้างข้อมูลทดลองบนอุปกรณ์นี้</button>':''}</section></div>`}
async function render(){const seq=++renderSequence;disposeViewer();chrome();try{if(route()==='orders')renderOrders();else if(route()==='history')renderHistory();else if(route()==='admin')await renderAdmin(seq);else if(route()==='settings')await renderSettings(seq);else renderFit()}catch(e){if(seq===renderSequence){$('#content').innerHTML=`<div class="empty-state"><h2>โหลดข้อมูลไม่สำเร็จ</h2><p>${esc(e.message)}</p><button data-action="refresh" class="button secondary">ลองอีกครั้ง</button></div>`}}}
function modal(title,subtitle,body,actions=''){const d=$('#modal');$('#modal-content').innerHTML=`<div class="modal-inner"><div class="modal-header"><h2>${title}</h2><button data-action="close-modal" class="modal-close" aria-label="ปิดหน้าต่าง">×</button></div>${subtitle?`<p class="modal-subtitle">${subtitle}</p>`:''}${body}${actions?`<div class="modal-actions">${actions}</div>`:''}</div>`;if(!d.open)d.showModal()}
function openLogin(){if(state.user){modal('บัญชีของคุณ',`${esc(state.user.name)} · ${esc(state.user.email)}`,`<p class="panel-note">${api.demo?'โหมดทดลอง — เปลี่ยนบทบาทเพื่อทดสอบผู้สั่งและแอดมินได้':'ตัวเลือกของคุณเชื่อมกับอีเมลนี้'}</p>`,`<button data-action="close-modal" class="button secondary">กลับ</button><button data-action="logout" class="button">${api.demo?'เปลี่ยนตัวตน':'ออกจากระบบ'}</button>`);return}if(api.demo){modal('ลองใช้ในมุมของคุณ','สลับทดลองได้ทั้งผู้สั่งและแอดมิน ไม่มีอีเมลส่งจริง',`<div class="demo-choice"><button data-action="demo-login" data-role="user">ผู้สั่งเสื้อ ↗<small>เลือกไซซ์ ยืนยัน และดูประวัติของตัวเอง</small></button><button data-action="demo-login" data-role="admin">แอดมิน ↗<small>ดูรายการ แก้ให้เพื่อน ล้างตัวเลือก และปิดระบบ</small></button></div>`);return}modal('เริ่มต้นด้วยอีเมลของคุณ','เราจะส่งรหัสยืนยันเพื่อให้คุณกลับมาจัดการรายการของตัวเองได้',`<form id="login-form"><div class="form-row"><label for="login-name">ชื่อที่ใช้ในรายการ</label><input id="login-name" name="name" required maxlength="100" autocomplete="name"></div><div class="form-row"><label for="login-email">อีเมล</label><input id="login-email" name="email" required type="email" maxlength="254" autocomplete="email"></div><div id="auth-error"></div><div class="modal-actions"><button class="button wide" type="submit">ส่งรหัสยืนยัน</button></div></form>`)}
function openConfirm(ids){if(!state.user){openLogin();return}if(closed()){notify('ระบบปิดรับการแก้ไขแล้ว',true);return}modal('ยืนยันตัวเลือกของคุณ','ตรวจไซซ์และทรงก่อนบันทึก แก้ไขได้จนกว่าจะปิดระบบ',ids.map(id=>{const p=PRODUCTS.find(p=>p.id===id);return `<div class="modal-item"><strong>${p.name}</strong><span>${itemLabel(state.drafts[id])}</span></div>`}).join('')+((ids.length===1&&!state.order.items[PRODUCTS.find(p=>p.id!==ids[0]).id])?'<p class="warning-note">หลังยืนยันตัวนี้ ยังต้องเลือกอีก 1 แบบให้ครบเซ็ต</p>':'')+(api.demo?'<p class="warning-note">ทดลองบันทึกบนอุปกรณ์นี้ ไม่ส่งไป Google Sheets</p>':''),`<button class="button secondary" data-action="close-modal">กลับไปปรับ</button><button class="button" data-action="commit" data-ids="${ids.join(',')}">${api.demo?'ยืนยันในโหมดทดลอง':'ยืนยันและบันทึก'}</button>`)}
function openAdmin(email,reset=false){const o=state.adminData?.orders.find(x=>x.email===email);if(!o)return;const choices=PRODUCTS.map(p=>`<div class="form-row"><label>${p.name}</label><div class="form-grid"><select name="${p.id}-size" aria-label="ไซซ์${p.name}"><option value="">ยังไม่เลือก</option>${SIZES.map(s=>`<option ${o.items[p.id]?.size===s?'selected':''}>${s}</option>`).join('')}</select><select name="${p.id}-fit" aria-label="ทรง${p.name}">${FITS.map(f=>`<option value="${f.id}" ${o.items[p.id]?.fit===f.id?'selected':''}>${f.name}</option>`).join('')}</select></div></div>`).join('');modal(reset?'ล้างรายการเพื่อเลือกใหม่':'แก้ไขรายการให้เพื่อน',`${esc(o.name)} · ${esc(o.email)}`,`<form id="admin-form" data-email="${esc(email)}" data-revision="${o.revision}" data-reset="${reset}">${reset?`<div class="form-row"><label for="reset-target">เลือกรายการที่ต้องการล้าง</label><select id="reset-target" name="resetTarget"><option value="both">ทั้ง 2 แบบ</option value="polo">เสื้อโปโลเท่านั้น</option><option value="tee">เสื้อยืดเท่านั้น</option></select></div><p class="warning-note">ตัวเลือกปัจจุบันจะถูกล้าง เจ้าของรายการต้องเข้ามาเลือกใหม่ ข้อมูลเดิมยังอยู่ในประวัติ</p>`:choices}<div class="form-row"><label for="reason">เหตุผลการ${reset?'ล้าง':'แก้ไข'} <span class="reason-required">จำเป็น</span></label><textarea id="reason" name="reason" required maxlength="500" placeholder="เช่น เจ้าของรายการแจ้งเปลี่ยนไซซ์"></textarea></div><p class="panel-note">${icon('mail')} ${api.demo?'จะจำลองอีเมลแจ้งเตือน ไม่ส่งจริง':'ระบบจะเข้าคิวอีเมลแจ้งเตือนเจ้าของรายการหลังบันทึก'}</p><div id="admin-error"></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-modal">ยกเลิก</button><button type="submit" class="button ${reset?'danger':''}">${reset?'ยืนยันล้างรายการ':'บันทึกการแก้ไข'}</button></div></form>`)}
function sizeGuide(){modal('ตารางไซซ์เสื้อ',`${state.sampleSizes?'ข้อมูลตัวอย่างสำหรับทดลองระบบ · ต้องแทนด้วยขนาดจริงจากผู้ผลิต':'ขนาดเสื้อจากการตั้งค่าระบบ'}<br>หน่วยนิ้ว · รอบอกทั้งทรงตรงและทรงเว้าเท่ากัน รอบเอวทรงเว้าเล็กกว่า`, `<div class="table-wrap"><table><thead><tr><th>ไซซ์</th><th>รอบอก</th><th>เอวทรงตรง</th><th>เอวทรงเว้า</th><th>ยาว</th></tr></thead><tbody>${SIZES.map(s=>{const m=measurements(s);return `<tr><td><strong>${s}</strong></td><td>${m.chest}</td><td>${m.waist}</td><td>${measurements(s,'shaped').waist}</td><td>${m.length}</td></tr>`}).join('')}</tbody></table></div><p class="warning-note">หุ่น 3 มิติใช้ขนาดตารางนี้เป็นแนวทาง ไม่มีการคำนวณความยืดหรือการทิ้งตัวของผ้า ควรวัดเสื้อที่ใส่สบายมาเทียบก่อนเลือก</p>`)}
async function run(fn,errorTarget){if(busy)return;busy=true;const buttons=[...document.querySelectorAll('#modal button,#content button[type="submit"]')].filter(b=>!b.disabled);buttons.forEach(b=>b.disabled=true);try{await fn()}catch(e){if(e.code==='CONFLICT'&&state.user){try{updateState(await api.load());$('#modal').close();await render()}catch{}}if(errorTarget&&$(errorTarget)&&$('#modal').open)$(errorTarget).innerHTML=`<div class="form-error">${esc(e.message)}</div>`;else notify(e.message,true);try{const d=await api.bootstrap();state.settings=d.settings;chrome()}catch{}}finally{busy=false;buttons.forEach(b=>{if(b.isConnected)b.disabled=false})}}
function exportCSV(){const rows=[['name','email','polo_fit','polo_size','tee_fit','tee_size','status','revision','updated_at'],...state.adminData.orders.map(o=>[o.name,o.email,o.items.polo?.fit,o.items.polo?.size,o.items.tee?.fit,o.items.tee?.size,orderStatus(o.items).label,o.revision,o.updatedAt])];const quote=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const csv='\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='threadroom-orders.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,v=b.dataset.value;
  if(['product','size','fit','body'].includes(a)){if(a==='product'){state.product=v}else if(a==='body'){state.body=v}else state.drafts[state.product][a]=v;render();return}
  if(a==='view'){state.view=b.dataset.view;state.auto=false;viewer?.setAngle(state.view==='front'?0:Math.PI);state.angle=state.view==='front'?0:Math.PI;document.querySelectorAll('[data-action="view"]').forEach(x=>x.classList.toggle('active',x===b));const auto=$('[data-action="auto"]');auto?.classList.remove('active');auto?.setAttribute('aria-pressed','false');return}
  if(a==='auto'){state.auto=viewer?.toggleAuto()||false;b.classList.toggle('active',state.auto);b.setAttribute('aria-pressed',String(state.auto));return}
  if(a==='zoom'){viewer?.setZoom();return}
  if(a==='login'){openLogin();return}if(a==='close-modal'){$('#modal').close();return}if(a==='sizeguide'){sizeGuide();return}
  if(a==='confirm-one'||a==='confirm-both'){openConfirm(a==='confirm-one'?[state.product]:PRODUCTS.map(p=>p.id));return}
  if(a==='edit-own'){state.product=v;location.hash='fit';if(route()==='fit')render();return}
  if(a==='admin-edit'||a==='admin-reset'){openAdmin(b.dataset.email,a==='admin-reset');return}
  if(a==='export'){exportCSV();return}
  run(async()=>{
    if(a==='demo-login'){updateState(await api.loginDemo(b.dataset.role));$('#modal').close();location.hash=b.dataset.role==='admin'?'admin':'fit';await render();notify('เข้าสู่โหมดทดลองแล้ว')}
    if(a==='logout'){await api.logout();state.user=null;state.order={items:clone(EMPTY_ITEMS),revision:0};state.logs=[];state.adminData=null;state.drafts={polo:{size:'M',fit:'straight'},tee:{size:'M',fit:'straight'}};$('#modal').close();location.hash='fit';await render();if(api.demo)openLogin()}
    if(a==='commit'){const ids=b.dataset.ids.split(',');const items=Object.fromEntries(ids.map(id=>[id,clone(state.drafts[id])]));const out=await api.save({items,expectedRevision:state.order.revision});state.order=out.order;updateState(await api.load());$('#modal').close();await render();notify(api.demo?'บันทึกตัวเลือกทดลองแล้ว':'บันทึกตัวเลือกแล้ว')}
    if(a==='refresh'){if(state.user)updateState(await api.load());else updateState(await api.bootstrap());await render();notify('โหลดข้อมูลล่าสุดแล้ว')}
    if(a==='seed'){await api.seed();await render();notify('เพิ่มสมาชิกตัวอย่างแล้ว')}
    if(a==='clear-demo'){modal('ล้างข้อมูลทดลองบนอุปกรณ์นี้','รายการ ประวัติ และการตั้งค่าทดลองจะกลับเป็นค่าเริ่มต้น','',`<button class="button secondary" data-action="close-modal">ยกเลิก</button><button class="button danger" data-action="clear-demo-confirm">ล้างข้อมูลทดลอง</button>`)}
    if(a==='clear-demo-confirm'){updateState(await api.clearDemo());$('#modal').close();await render();notify('ล้างข้อมูลทดลองแล้ว')}
  })
});
document.addEventListener('input',e=>{if(e.target.id==='admin-search')$('#admin-rows').innerHTML=adminRows(state.adminData.orders,e.target.value)});
document.addEventListener('submit',e=>{const form=e.target;if(!['login-form','otp-form','admin-form','settings-form'].includes(form.id))return;e.preventDefault();const f=new FormData(form);
  run(async()=>{
    if(form.id==='login-form'){const email=String(f.get('email')).trim().toLowerCase(),name=String(f.get('name')).trim();await api.requestCode(email,name);modal('ตรวจสอบอีเมลของคุณ',`ส่งรหัสไปที่ ${esc(email)} แล้ว รหัสมีอายุ 10 นาที`, `<form id="otp-form" data-email="${esc(email)}"><div class="form-row"><label for="otp-code">รหัสยืนยัน 8 หลัก</label><input id="otp-code" name="code" required pattern="[0-9]{8}" inputmode="numeric" autocomplete="one-time-code" maxlength="8"></div><div id="auth-error"></div><div class="modal-actions"><button type="submit" class="button wide">ยืนยันและเข้าสู่ระบบ</button></div></form>`)}
    if(form.id==='otp-form'){updateState(await api.verifyCode(form.dataset.email,String(f.get('code')).trim()));$('#modal').close();await render();notify('เข้าสู่ระบบแล้ว')}
    if(form.id==='admin-form'){const email=form.dataset.email,reset=form.dataset.reset==='true';let items={};if(reset){const ids=f.get('resetTarget')==='both'?PRODUCTS.map(p=>p.id):[f.get('resetTarget')];items=Object.fromEntries(ids.map(id=>[id,null]))}else{for(const p of PRODUCTS){const size=f.get(p.id+'-size');items[p.id]=size?{size,fit:f.get(p.id+'-fit')}:null}}
      const out=await api.save({items,reason:String(f.get('reason')).trim(),expectedRevision:Number(form.dataset.revision)},email);if(state.user.email===email)updateState(await api.load());$('#modal').close();await render();notify(out.mailStatus==='demo'?'บันทึกแล้ว · จำลองอีเมลแจ้งเจ้าของรายการ':'บันทึกแล้ว · เข้าคิวส่งอีเมลแจ้งเจ้าของรายการ')}
    if(form.id==='settings-form'){const date=String(f.get('closeAt')||'');const data=await api.updateSettings({open:f.get('open')==='on',closeAt:date?new Date(date).toISOString():'',expectedRevision:state.settings.revision});state.settings=data.settings;await render();notify('บันทึกการตั้งค่าแล้ว')}
  },form.id==='admin-form'?'#admin-error':form.id.includes('form')&&form.id!=='settings-form'?'#auth-error':null)
});
$('#login-top').addEventListener('click',openLogin);$('#account').addEventListener('click',openLogin);window.addEventListener('hashchange',()=>render());
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.user)api.load().then(d=>{updateState(d);render()}).catch(e=>notify(e.message,true))});
setInterval(()=>{const was=$('#system-badge').classList.contains('closed');if(was!==closed()){chrome();render()}},15000);
async function start(){try{updateState(await api.bootstrap());if(!api.demo&&api.token){try{updateState(await api.load())}catch{notify('เซสชันหมดอายุ กรุณาเข้าสู่ระบบอีกครั้ง',true)}}await render()}catch(e){$('#content').innerHTML=`<div class="empty-state"><h2>ยังเชื่อมต่อระบบไม่ได้</h2><p>${esc(e.message)}</p><button data-action="refresh" class="button secondary">ลองใหม่</button></div>`}}
start();
